            fromVersion?: string;
            /** @description The highest version a package's allow delivers (R-CUR-026); absent for no upper bound. */
            toVersion?: string;
            /** @description Whether `toVersion` is delivered; false delivers the versions below it. True when absent. */
            toInclusive?: boolean;
